package com.google.gson.stream;

import com.google.gson.stream.JsonWriter;
import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.Writer;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.Random;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;

public class JsonWriter_value_TriageGen0Test {

    @Test
    public void testValue_Null() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new java.io.StringWriter());
        jsonWriter.setLenient(true);
        Object result = jsonWriter.value(null);
        assertNull(result);
    }

    @Test
    public void testValue_NotNull() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new java.io.StringWriter());
        jsonWriter.setLenient(true);
        jsonWriter.value(10);
        jsonWriter.flush();
        assertEquals("{\"value\":10}", new java.io.StringReader(jsonWriter.out.toString()).readAll());
    }

    @Test
    public void testValue_Infinity() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new java.io.StringWriter());
        jsonWriter.setLenient(false);
        assertThrows(IllegalArgumentException.class, () -> jsonWriter.value(Double.POSITIVE_INFINITY));
    }

    @Test
    public void testValue_NaN() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new java.io.StringWriter());
        jsonWriter.setLenient(false);
        assertThrows(IllegalArgumentException.class, () -> jsonWriter.value(Double.NaN));
    }

    @Test
    public void testValue_String() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new java.io.StringWriter());
        jsonWriter.setLenient(true);
        jsonWriter.value("hello");
        jsonWriter.flush();
        assertEquals("{\"value\":\"hello\"}", new java.io.StringReader(jsonWriter.out.toString()).readAll());
    }

    @Test
    public void testValue_BigInteger() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new java.io.StringWriter());
        jsonWriter.setLenient(true);
        jsonWriter.value(BigInteger.valueOf(10));
        jsonWriter.flush();
        assertEquals("{\"value\":10}", new java.io.StringReader(jsonWriter.out.toString()).readAll());
    }

    @Test
    public void testValue_BigDecimal() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new java.io.StringWriter());
        jsonWriter.setLenient(true);
        jsonWriter.value(new BigDecimal("10.5"));
        jsonWriter.flush();
        assertEquals("{\"value\":\"10.5\"}", new java.io.StringReader(jsonWriter.out.toString()).readAll());
    }

    @Test
    public void testValue_Random() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new java.io.StringWriter());
        jsonWriter.setLenient(true);
        Random random = new Random();
        jsonWriter.value(random.nextLong());
        jsonWriter.flush();
        assertEquals("{\"value\":", new java.io.StringReader(jsonWriter.out.toString()).readAll());
    }

    @Test
    public void testValue_SetLenient() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new java.io.StringWriter());
        jsonWriter.setLenient(false);
        jsonWriter.value(10);
        jsonWriter.flush();
        assertEquals("{\"value\":10}", new java.io.StringReader(jsonWriter.out.toString()).readAll());
    }

}
